            let exact_sdf = r - r_target;
            let diff = (phi[j * nx + i] / (2.0 * r.max(0.1)) - exact_sdf).abs();
            if diff > max_grad_err && (r - r_target).abs() < 0.2 { max_grad_err = diff; }
